-- Staff must not reconcile while a compensating deletion is still in flight.
-- Null leases remain valid for unresolved operations created by Python.
ALTER TABLE publication_operations DROP CONSTRAINT ck_publication_operations_state_shape;
ALTER TABLE publication_operations ADD CONSTRAINT ck_publication_operations_state_shape CHECK ((status = 'copying' AND lease_expires_at IS NOT NULL AND channel_message_id IS NULL AND published_at IS NULL AND published_post_id IS NULL) OR (status = 'compensating' AND channel_message_id IS NOT NULL AND published_at IS NOT NULL AND published_post_id IS NULL) OR (status = 'completed' AND lease_expires_at IS NULL AND channel_message_id IS NOT NULL AND published_at IS NOT NULL AND published_post_id IS NOT NULL) OR (status IN ('uncertain', 'failed') AND lease_expires_at IS NULL AND channel_message_id IS NULL AND published_at IS NULL AND published_post_id IS NULL) OR (status = 'abandoned' AND lease_expires_at IS NULL AND published_post_id IS NULL AND ((channel_message_id IS NULL AND published_at IS NULL) OR (channel_message_id IS NOT NULL AND published_at IS NOT NULL))));
